"""Goal GC guard table own_b_019 (PNC-019 C12-GC Method B; generated by scripts/pm-goal-gc-guard-tables.py --generate).

One owner predicate per row, in the complete checker's evaluation order. Every row of this table is
evaluated by exactly the same accepted complete calls. Predicates read only their own derived observation;
the checker derives each observation from the complete input and decides nothing itself.
"""
import pm_guard_isolation as g

FIELDS = ('blocked_edge', 'blocked_reason', 'blocked_changed',)


def R01_blocked_edge(value, context):
    return 'blocked/edge' if value['blocked_edge'] is not True else None


def R02_blocked_reason(value, context):
    return 'blocked/reason' if value['blocked_reason'] is not True else None


def R03_blocked_changed(value, context):
    return 'blocked/changed' if value['blocked_changed'] is not True else None


def case(value):
    context = None
    table = g.GuardTable([
        g.Guard('R01_blocked_edge', g.Invariant('/blocked_edge', 'owner predicate blocked/edge at scripts/pm_goal_own_b_oracles.py:376'), 'blocked/edge', R01_blocked_edge),
        g.Guard('R02_blocked_reason', g.Invariant('/blocked_reason', 'owner predicate blocked/reason at scripts/pm_goal_own_b_oracles.py:377'), 'blocked/reason', R02_blocked_reason),
        g.Guard('R03_blocked_changed', g.Invariant('/blocked_changed', 'owner predicate blocked/changed at scripts/pm_goal_own_b_oracles.py:378'), 'blocked/changed', R03_blocked_changed),
    ])

    def check(value):
        table.require('R01_blocked_edge', value, context)
        table.require('R02_blocked_reason', value, context)
        table.require('R03_blocked_changed', value, context)
        return True
    return g.Case(table, check, context)
